CREATE FUNCTION public.claim_provider_invitation(_ws uuid,_action text,_id uuid,_email text,_type text,_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE i public.account_connection_invitations; wid text; pid text; normalized text; rid uuid; BEGIN
IF NOT public.can_manage_account_connections(_ws) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type='provider' AND status='active' AND NOT is_test_account) OR _action NOT IN ('send','resend') THEN RAISE EXCEPTION 'Invitation unavailable'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='account_invitation_delivery' AND enabled) THEN RAISE EXCEPTION 'Invitation delivery is not enabled'; END IF;
IF _hash IS NULL OR _hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid invitation'; END IF;
PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
IF _action='resend' THEN SELECT * INTO i FROM public.account_connection_invitations WHERE id=_id AND inviter_workspace_id=_ws FOR UPDATE; IF NOT FOUND OR i.status<>'pending' THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; normalized:=i.recipient_email; _type:=coalesce(i.intended_account_type,i.intended_type);
ELSE normalized:=lower(trim(_email)); END IF;
IF normalized IS NULL OR length(normalized)>254 OR normalized !~ '^[^ @]+@[^ @]+\.[^ @]+$' OR _type IS NULL OR _type NOT IN ('patient','facility') THEN RAISE EXCEPTION 'Invalid invitation'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(normalized,0));
SELECT mfn_id INTO pid FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO wid FROM public.workspaces WHERE id=_ws;
IF (SELECT count(*) FROM public.account_relationship_events WHERE workspace_id=_ws AND action='invitation_delivery_claimed' AND created_at>now()-interval '1 hour')>=5 OR (SELECT count(*) FROM public.account_relationship_events WHERE action='invitation_delivery_claimed' AND details->>'recipientEmail'=normalized AND created_at>now()-interval '1 day')>=3 OR EXISTS(SELECT 1 FROM public.account_relationship_events WHERE action='invitation_delivery_claimed' AND details->>'recipientEmail'=normalized AND created_at>now()-interval '5 minutes') THEN RAISE EXCEPTION 'Please wait before sending another invitation'; END IF;
IF _action='send' THEN SELECT * INTO i FROM public.account_connection_invitations WHERE inviter_workspace_id=_ws AND recipient_email=normalized AND coalesce(intended_account_type,intended_type)=_type AND status='pending' AND expires_at>now() ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF FOUND THEN RETURN jsonb_build_object('id',i.id,'generation',i.generation,'duplicate',true); END IF;
INSERT INTO public.account_connection_invitations(inviter_workspace_id,recipient_email,intended_type,intended_account_type,token_hash,expires_at,created_by,person_mfn_id,workspace_mfn_id,delivery_status) VALUES(_ws,normalized,'facility',_type,_hash,now()+interval '7 days',auth.uid(),pid,wid,'sending') RETURNING * INTO i;
ELSE UPDATE public.account_connection_invitations SET token_hash=_hash,expires_at=now()+interval '7 days',generation=generation+1,delivery_status='sending',updated_at=now() WHERE id=i.id RETURNING * INTO i; END IF;
INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,i.id,'invitation_delivery_claimed',auth.uid(),pid,wid,jsonb_build_object('recipientEmail',normalized,'generation',i.generation,'intendedType',_type));
RETURN jsonb_build_object('id',i.id,'reference',i.mfn_id,'generation',i.generation,'duplicate',false,'recipientEmail',normalized,'intendedType',_type);
END $$;
REVOKE ALL ON FUNCTION public.claim_provider_invitation(uuid,text,uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_provider_invitation(uuid,text,uuid,text,text,text) TO authenticated;
COMMENT ON FUNCTION public.claim_provider_invitation(uuid,text,uuid,text,text,text) IS 'Confirmed provider invitation delivery claim; existing records, serialized recipient/workspace limits, seven-day hash-only setup and missing delivery flag OFF.';